S=/private/tmp/claude-502/-Users-chengzheng-Desktop-Files-tigerless-apsu-home-page-init/b88f38d4-6900-41d6-855b-a41a6443cbce/scratchpad/figma; node - "$S/page-0-1.xml" <<'EOF'
const fs=require('fs');const lines=fs.readFileSync(process.argv[2],'utf8').split('\n');
const ind=l=>l.match(/^ */)[0].length;
const attr=(l,k)=>{const m=l.match(new RegExp(k+'="([^"]*)"'));return m?m[1]:''};
function sections(rootId,label){
  const start=lines.findIndex(l=>l.includes(`id="${rootId}"`));
  const base=ind(lines[start]);
  console.log(`\n=== ${label} (${rootId}) ===`);
  let i=start+1;
  while(i<lines.length && ind(lines[i])>base){
    const l=lines[i];
    if(ind(l)===base+2 && /^ *<(frame|instance|rectangle|rounded-rectangle|text|vector)/.test(l)){
      const id=attr(l,'id'),name=attr(l,'name'),y=attr(l,'y'),h=attr(l,'height'),w=attr(l,'width');
      // collect text names inside this section (first 8)
      const texts=[];let j=i+1;
      while(j<lines.length && ind(lines[j])>base+2){ if(/<text /.test(lines[j])){const t=attr(lines[j],'name');if(t&&!texts.includes(t))texts.push(t);} j++; }
      console.log(`${id.padEnd(10)} ${name.padEnd(22)} y=${y.padStart(5)} h=${h.padStart(5)} w=${w}  texts=${texts.length}: ${texts.slice(0,7).map(t=>JSON.stringify(t.slice(0,28))).join(' ')}`);
    }
    i++;
  }
}
